head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[autoComplete > P > valueNotInList]<br/>아이템 리스트에 없는 아이템을 선택했을때 처리하는 방식을 설정합니다.",
    "validation" : [        
        "customlabelFormatter, displayMode 등의 속성은 아이템 표시 영역에 적용되지 않습니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {                
        emptyItem : true,
        valueNotInList : "keepValue",
        displayMode : "value delim label",
        delimiter : "_",
    }

    let cList = $c.gcm.createCList(properties)

    // target 생성    
    $c.gcm.createLabel('label="displayMode=value delim label, valueNotInList=keepValue 설정된 상태에서 setValue(100) 시 빈 값 출력되면 정상"', '', 'label1');
    $c.gcm.createBasicAutoComplete(cList);
}



scwin.btn_setValue_onclick = function (e) {
	target1.setValue(100);
    scwin.btn_getInfo_onclick();
};



scwin.btn_getInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getText();
	wf_body_bottom.getObj("scwin").setReturnValue("getText : " + rtn);

    rtn = target1.getValue();
	wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + rtn);    

    rtn = target1.getSelectedIndex();
	wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex : " + rtn);
};
